// Avoiding the use of dynamic import for now since we have
// some users being on older Angular versions etc. that are
// having trouble getting the SDK to work for them.
// See https://spacemakercore.slack.com/archives/C06H3MYQXLM/p1707733857716509
async function loadModule(src) {
    await new Promise((resolve, reject) => {
        const scripts = Array.from(document.querySelectorAll("script"));
        if (scripts.some((script) => script.src.endsWith(src))) {
            resolve(undefined);
            return;
        }
        const script = document.createElement("script");
        script.type = "module";
        script.src = src;
        script.onload = () => {
            resolve(undefined);
        };
        script.onerror = (message) => {
            // eslint-disable-next-line @typescript-eslint/prefer-promise-reject-errors
            reject(message);
        };
        document.head.append(script);
    });
}
export class FormaLoginOverlay extends HTMLElement {
    #shadow;
    constructor() {
        super();
        this.#shadow = this.attachShadow({ mode: "open" });
    }
    connectedCallback() {
        if (!customElements.get("weave-button")) {
            void loadModule("https://app.autodeskforma.com/design-system/v2/weave/components/button/weave-button.js");
        }
        this.#shadow.appendChild(getTemplate().content.cloneNode(true));
        const namePlaceholder = this.#shadow.getElementById("name-placeholder");
        const name = this.getAttribute("extension-name");
        if (namePlaceholder && name) {
            namePlaceholder.textContent = this.getAttribute("extension-name");
        }
        const loginButton = this.#shadow.getElementById("login-button");
        if (!loginButton)
            return;
        loginButton.addEventListener("click", () => {
            this.dispatchEvent(new Event("loginclick", {
                bubbles: true,
                composed: true,
            }));
        });
    }
}
/**
 * Define the login overlay component if it is not already defined.
 */
export function defineLoginOverlayComponent() {
    if (!customElements.get("forma-login-overlay")) {
        customElements.define("forma-login-overlay", FormaLoginOverlay);
    }
}
